<?php
require_once __DIR__.'/includes/functions.php';require_login();$items=cart_items();if(!$items){flash('error','Your bag is empty.');redirect('cart.php');}$page_title='Checkout';$errors=[];$couponResult=apply_coupon((string)($_SESSION['coupon_code']??''),cart_subtotal());$couponCode=(string)($_SESSION['coupon_code']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');
if($action==='coupon'){ $test=apply_coupon((string)($_POST['coupon']??''),cart_subtotal());if($test['ok']){$_SESSION['coupon_code']=strtoupper(trim((string)($_POST['coupon']??'')));flash('success',$test['message']);}else{unset($_SESSION['coupon_code']);flash('error',$test['message']);}redirect('checkout.php');}
$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));$city=trim((string)($_POST['city']??''));$state=trim((string)($_POST['state']??''));$pin=trim((string)($_POST['postal_code']??''));$payment=(string)($_POST['payment_method']??'cod');
if(strlen($name)<2||strlen($phone)<8||strlen($address)<8||strlen($city)<2||strlen($state)<2||!preg_match('/^[0-9]{6}$/',$pin))$errors[]='Please complete all delivery fields correctly.';
if(!in_array($payment,['cod','razorpay'],true))$errors[]='Choose a valid payment method.';
if($payment==='razorpay'&&!is_razorpay_configured())$errors[]='Online payment is not configured. Choose Cash on Delivery.';
if(!$errors){
 try{$pdo=db();$pdo->beginTransaction();$subtotal=0;$fresh=[];
  $lock=$pdo->prepare('SELECT id,name,price,sale_price,stock,active FROM products WHERE id=? FOR UPDATE');
  foreach($items as $it){$lock->execute([(int)$it['id']]);$prod=$lock->fetch();if(!$prod||!$prod['active']||(int)$prod['stock']<(int)$it['quantity'])throw new RuntimeException('A product is out of stock or its quantity changed.');$unit=((float)$prod['sale_price']>0&&(float)$prod['sale_price']<(float)$prod['price'])?(float)$prod['sale_price']:(float)$prod['price'];$subtotal+=$unit*(int)$it['quantity'];$prod['quantity']=(int)$it['quantity'];$prod['unit_price']=$unit;$fresh[]=$prod;}
  $coupon=apply_coupon((string)($_SESSION['coupon_code']??''),$subtotal);if(!$coupon['ok']){$coupon=['discount'=>0,'coupon'=>null];}
  $shipping=$subtotal>=1499?0:99;$discount=(float)$coupon['discount'];$total=max(0,round($subtotal+$shipping-$discount,2));
  $orderNo='SC'.date('ymd').strtoupper(bin2hex(random_bytes(3)));
  $ins=$pdo->prepare('INSERT INTO orders (order_number,user_id,full_name,phone,address,city,state,postal_code,subtotal,shipping,discount,total,payment_method,payment_status,status,coupon_code) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
  $payStatus=$payment==='cod'?'pending':'created';
  $ins->execute([$orderNo,current_user()['id'],$name,$phone,$address,$city,$state,$pin,$subtotal,$shipping,$discount,$total,$payment,$payStatus,'pending',$coupon['coupon']['code']??null]);$orderId=(int)$pdo->lastInsertId();
  $oi=$pdo->prepare('INSERT INTO order_items (order_id,product_id,product_name,unit_price,quantity,line_total) VALUES (?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');
  foreach($fresh as $prod){$qty=$prod['quantity'];$oi->execute([$orderId,$prod['id'],$prod['name'],$prod['unit_price'],$qty,$prod['unit_price']*$qty]);$stock->execute([$qty,$prod['id']]);}
  if($coupon['coupon']){$use=$pdo->prepare('INSERT INTO coupon_uses(coupon_id,user_id,order_id) VALUES(?,?,?)');$use->execute([$coupon['coupon']['id'],current_user()['id'],$orderId]);}
  $pdo->commit();unset($_SESSION['cart'],$_SESSION['coupon_code']);
  if($payment==='cod'){flash('success','Order placed successfully.');redirect('order.php?id='.$orderId);}
  $_SESSION['pending_payment_order']=$orderId;redirect('pay.php?order='.$orderId);
 }catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$errors[]=$ex instanceof RuntimeException?$ex->getMessage():'Unable to place order. Please retry.';}
}
}
$items=cart_items();$subtotal=cart_subtotal();$couponResult=apply_coupon((string)($_SESSION['coupon_code']??''),$subtotal);$discount=$couponResult['ok']?$couponResult['discount']:0;$shipping=$subtotal>=1499?0:99;$total=max(0,$subtotal+$shipping-$discount);
include __DIR__.'/includes/header.php'; ?>
<div class="container py-5"><span class="eyebrow">Almost there</span><h1 class="section-title mt-2 mb-4">Checkout</h1><?php foreach($errors as $er): ?><div class="alert alert-danger"><?= e($er) ?></div><?php endforeach; ?><div class="row g-5"><div class="col-lg-7"><form method="post" class="border p-4"><?= csrf_field() ?><input type="hidden" name="action" value="place"><h4 class="mb-3">Delivery details</h4><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" required value="<?= e($_POST['full_name']??current_user()['name']) ?>"><label class="form-label">Phone</label><input class="form-control mb-3" name="phone" required maxlength="20" value="<?= e($_POST['phone']??'') ?>"><label class="form-label">Address</label><textarea class="form-control mb-3" name="address" required rows="3"><?= e($_POST['address']??'') ?></textarea><div class="row"><div class="col-md-6"><label class="form-label">City</label><input class="form-control mb-3" name="city" required value="<?= e($_POST['city']??'') ?>"></div><div class="col-md-6"><label class="form-label">State</label><input class="form-control mb-3" name="state" required value="<?= e($_POST['state']??'') ?>"></div></div><label class="form-label">PIN code</label><input class="form-control mb-4" name="postal_code" pattern="[0-9]{6}" maxlength="6" required value="<?= e($_POST['postal_code']??'') ?>"><h4 class="mb-3">Payment method</h4><div class="form-check mb-2"><input class="form-check-input" type="radio" name="payment_method" value="cod" id="cod" checked><label class="form-check-label" for="cod">Cash on Delivery</label></div><?php if(is_razorpay_configured()): ?><div class="form-check mb-4"><input class="form-check-input" type="radio" name="payment_method" value="razorpay" id="razorpay"><label class="form-check-label" for="razorpay">Pay online with Razorpay</label></div><?php else: ?><p class="small muted mb-4">Online payments become available after Razorpay test keys are configured.</p><?php endif; ?><button class="btn btn-dark w-100">Place order · <?= money($total) ?></button></form></div><div class="col-lg-5"><div class="summary-box"><h4>Order summary</h4><?php foreach($items as $it): ?><div class="d-flex justify-content-between gap-3 my-3"><span><?= e($it['name']) ?> × <?= (int)$it['quantity'] ?></span><strong><?= money($it['line_total']) ?></strong></div><?php endforeach; ?><hr><form method="post" class="mb-3"><?= csrf_field() ?><input type="hidden" name="action" value="coupon"><label class="form-label">Promo code</label><div class="input-group"><input class="form-control" name="coupon" placeholder="WELCOME10" value="<?= e($couponCode) ?>"><button class="btn btn-outline-dark">Apply</button></div></form><?php if($couponCode&&$couponResult['ok']): ?><p class="small text-success"><?= e($couponCode) ?> applied</p><?php endif; ?><div class="d-flex justify-content-between my-2"><span>Subtotal</span><span><?= money($subtotal) ?></span></div><div class="d-flex justify-content-between my-2"><span>Shipping</span><span><?= $shipping?'₹99':'FREE' ?></span></div><div class="d-flex justify-content-between my-2"><span>Discount</span><span>−<?= money($discount) ?></span></div><hr><div class="d-flex justify-content-between fs-5 fw-bold"><span>Total</span><span><?= money($total) ?></span></div></div></div></div></div>
<?php include __DIR__.'/includes/footer.php'; ?>
